// apps/api/src/repositories/workspaceRepository.ts
init_supabaseClient();
var WorkspaceRepository = class {
  /**
   * Retrieves the primary or personal workspace for a user.
   */
  async getPrimaryWorkspaceForUser(userId) {
    const supabase = getSupabaseAdmin();
    if (!supabase) {
      return null;
    }
    const { data: membership, error: memError } = await supabase.from("workspace_members").select("workspace_id, role, workspaces(*)").eq("user_id", userId).limit(1).single();
    if (memError || !membership) {
      const { data: ownedWs } = await supabase.from("workspaces").select("*").eq("owner_id", userId).limit(1).single();
      if (ownedWs) {
        return {
          id: ownedWs.id,
          name: ownedWs.name,
          ownerId: ownedWs.owner_id,
          isPersonal: ownedWs.is_personal,
          role: "owner",
          createdAt: ownedWs.created_at,
          updatedAt: ownedWs.updated_at
        };
      }
      return null;
    }
    const ws = membership.workspaces;
    return {
      id: ws.id,
      name: ws.name,
      ownerId: ws.owner_id,
      isPersonal: ws.is_personal,
      role: membership.role,
      createdAt: ws.created_at,
      updatedAt: ws.updated_at
    };
  }
  /**
   * Ensures a personal workspace exists for a user and returns its ID.
   */
  async ensurePersonalWorkspace(userId, email) {
    const existing = await this.getPrimaryWorkspaceForUser(userId);
    if (existing) return existing.id;
    const supabase = getSupabaseAdmin();
    if (!supabase) {
      throw new Error("Supabase database client is not configured.");
    }
    await supabase.from("profiles").upsert({
      id: userId,
      email,
      full_name: email.split("@")[0]
    });
    const { data: ws, error: wsError } = await supabase.from("workspaces").insert({
      name: "Personal Workspace",
      owner_id: userId,
      is_personal: true
    }).select().single();
    if (wsError || !ws) {
      console.error("ensurePersonalWorkspace error:", wsError);
      throw new Error(`Failed to create personal workspace: ${wsError?.message || "Unknown database error"}`);
    }
    await supabase.from("workspace_members").insert({
      workspace_id: ws.id,
      user_id: userId,
      role: "owner"
    });
    await supabase.from("credit_balances").insert({
      workspace_id: ws.id,
      balance: 50,
      held_balance: 0,
      lifetime_granted: 50,
      lifetime_spent: 0
    });
    await supabase.from("credit_ledger").insert({
      workspace_id: ws.id,
      actor_user_id: userId,
      amount: 50,
      resulting_balance: 50,
      type: "signup_grant",
      idempotency_key: `signup_grant_${ws.id}`,
      description: "Welcome signup grant of 50 credits",
      metadata: { initial_grant: true, is_personal: true }
    });
    return ws.id;
  }
  /**
   * Lists all workspaces accessible by a user.
   */
  async getUserWorkspaces(userId) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return [];
    const { data, error } = await supabase.from("workspace_members").select("workspace_id, role, workspaces(*)").eq("user_id", userId);
    if (error || !data) {
      console.error("WorkspaceRepository.getUserWorkspaces error:", error);
      return [];
    }
    return data.filter((d) => d.workspaces).map((d) => ({
      id: d.workspaces.id,
      name: d.workspaces.name,
      ownerId: d.workspaces.owner_id,
      isPersonal: d.workspaces.is_personal,
      role: d.role,
      createdAt: d.workspaces.created_at,
      updatedAt: d.workspaces.updated_at
    }));
  }
  /**
   * Lists members of a given workspace.
   */
  async getWorkspaceMembers(workspaceId) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return [];
    const { data, error } = await supabase.from("workspace_members").select("workspace_id, user_id, role, joined_at, profiles(*)").eq("workspace_id", workspaceId);
    if (error || !data) {
      console.error("WorkspaceRepository.getWorkspaceMembers error:", error);
      return [];
    }
    return data;
  }
  /**
   * Verifies if a user is an authorized member (owner, admin, member) of a workspace.
   */
  async isUserMemberOfWorkspace(userId, workspaceId) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return false;
    const { data: memberData, error: memberError } = await supabase.from("workspace_members").select("role").eq("user_id", userId).eq("workspace_id", workspaceId).maybeSingle();
    if (!memberError && memberData) {
      return true;
    }
    const { data: ownerData, error: ownerError } = await supabase.from("workspaces").select("id").eq("id", workspaceId).eq("owner_id", userId).maybeSingle();
    return Boolean(!ownerError && ownerData);
  }
};
var workspaceRepository = new WorkspaceRepository();

// apps/api/src/modules/ai/aiRoutes.ts
init_billingErrorUtils();
var aiRouter = Router();
aiRouter.post("/generate-content", async (req, res) => {
  const { data, error } = validateGenerateContentInput(req.body);
  if (error) {
    return res.status(error.status).json({ error: error.message, code: error.code });
  }
  if (!req.user || !req.user.uid) {
    return res.status(401).json({ error: "Unauthorized: Authenticated user session required.", code: "AUTH_REQUIRED" });
  }
  const userId = req.user.uid;
  const userIdentifier = req.user.email || req.user.uid;
  const clientKey = req.headers["x-idempotency-key"] || `ai_${Date.now()}_${Math.random().toString(36).substring(7)}`;
  const workspaceId = req.user.workspaceId || await workspaceRepository.ensurePersonalWorkspace(userId, req.user.email || "");
  let holdId = null;
  let jobId = null;
  const requestedModel = (data?.model || "").toLowerCase();
  let creditsRequired = 1;
  if (requestedModel.includes("flash-image") || requestedModel.includes("schnell")) {
    creditsRequired = 2;
  } else if (requestedModel.includes("gpt-image-2") || requestedModel.includes("fal studio")) {
    creditsRequired = 3;
  } else if (requestedModel.includes("flux/dev") || requestedModel.includes("flux-pro")) {
    creditsRequired = 4;
  } else if (requestedModel.includes("veo-3.1-lite")) {
    creditsRequired = 10;
  } else if (requestedModel.includes("veo-3.1-fast")) {
    creditsRequired = 20;
  } else if (requestedModel.includes("veo-3.1") || requestedModel.includes("kling")) {
    creditsRequired = 40;
  } else if (requestedModel.includes("seedance")) {
    creditsRequired = 80;
  } else if (requestedModel.includes("pro") && !requestedModel.includes("flux")) {
    creditsRequired = 5;
  } else {
    creditsRequired = 1;
  }
  try {
    const reservation = await creditService.reserveCredits({
      workspaceId,
      userId,
      amount: creditsRequired,
      referenceId: clientKey,
      description: `AI Generation (${data.model})`,
      idempotencyKey: `hold_${clientKey}`
    });
    if (!reservation.success) {
      let serviceName = "AI Content Generation";
      if (requestedModel.includes("veo") || requestedModel.includes("kling") || requestedModel.includes("seedance")) {
        serviceName = "Video Generation";
      } else if (requestedModel.includes("image") || requestedModel.includes("flux") || requestedModel.includes("schnell")) {
        serviceName = "Image Generation";
      } else {
        serviceName = "Copywriting & Content";
      }
      return sendInsufficientCreditsResponse(res, {
        service: serviceName,
        model: data?.model,
        required: creditsRequired,
        available: reservation.available
      });
    }
    holdId = reservation.holdId || reservation.hold_id || null;
    const job = await aiJobRepository.createJob({
      workspaceId,
      requestedBy: userId,
      operation: "generate-content",
      provider: "google-gemini",
      modelRequested: data.model,
      creditsReserved: creditsRequired,
      idempotencyKey: `job_${clientKey}`
    });
    jobId = job?.id || null;
    const result = await orchestrateGenerateContent(data, userIdentifier);
    let newBalance;
    if (holdId) {
      const captureResult = await creditService.captureCredits(holdId, `capture_${clientKey}`);
      newBalance = captureResult.newBalance ?? captureResult?.new_balance;
      if (jobId) {
        await aiJobRepository.completeJob({
          jobId,
          modelUsed: result.modelUsed,
          creditsCharged: creditsRequired,
          outputs: []
        });
        await aiJobRepository.recordUsage({
          workspaceId,
          userId,
          jobId,
          provider: "google-gemini",
          model: result.modelUsed,
          operation: "generate-content",
          inputUnits: 100,
          outputUnits: 200,
          providerCostMicrounits: 1250,
          // Micro-dollars ($0.001250)
          creditsCharged: creditsRequired
        });
      }
    }
    return res.json({
      ...result,
      newBalance
    });
  } catch (err) {
    if (holdId) {
      await creditService.releaseCredits(holdId, err?.message || "AI Generation Failed");
    }
    if (jobId) {
      await aiJobRepository.failJob(jobId, err?.code || "AI_FAILED", err?.message || "Generation error");
    }
    const status = err?.status || 500;
    const statusCode = typeof status === "number" && status >= 400 && status < 600 ? status : 500;
    return res.status(statusCode).json({
      error: err?.message || "Failed to generate AI content",
      code: err?.code || "AI_GENERATION_FAILED"
    });
  }
});
