init_supabaseClient();
var ALLOWED_TRANSITIONS = {
  created: ["created", "authorized", "captured", "failed", "expired"],
  authorized: ["authorized", "captured", "failed", "expired"],
  captured: ["captured", "refunded", "partially_refunded"],
  failed: ["failed"],
  expired: ["expired"],
  refunded: ["refunded"],
  partially_refunded: ["partially_refunded", "refunded"]
};
var PaymentRepository = class {
  /**
   * Validates if a transition from current status to next status is permitted.
   */
  isValidTransition(current, next2) {
    const allowed = ALLOWED_TRANSITIONS[current];
    return allowed ? allowed.includes(next2) : false;
  }
  async create(record) {
    const supabase = getSupabaseAdmin();
    if (!supabase) {
      return null;
    }
    const { data, error } = await supabase.from("payments").insert({
      workspace_id: record.workspaceId,
      user_id: record.userId,
      order_id: record.orderId,
      plan_id: record.planId,
      amount_subunits: record.amountSubunits,
      currency: record.currency || "USD",
      status: "created",
      is_simulated: Boolean(record.isSimulated),
      idempotency_key: record.idempotencyKey || `order_${record.orderId}`
    }).select().single();
    if (error || !data) {
      console.error("PaymentRepository.create error:", error);
      return null;
    }
    return this.mapRow(data);
  }
  async updateStatus(params) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return true;
    const existing = await this.getByOrderId(params.orderId);
    if (existing) {
      if (!this.isValidTransition(existing.status, params.status)) {
        console.warn(
          `PaymentRepository: Rejected illegal status transition from "${existing.status}" to "${params.status}" for order ${params.orderId}`
        );
        return false;
      }
      if (existing.status === params.status && existing.paymentId === params.paymentId) {
        return true;
      }
    }
    const updates = {
      status: params.status,
      updated_at: (/* @__PURE__ */ new Date()).toISOString()
    };
    if (params.paymentId) updates.payment_id = params.paymentId;
    if (params.signature) updates.signature = params.signature;
    if (params.providerEventId) updates.provider_event_id = params.providerEventId;
    const { error } = await supabase.from("payments").update(updates).eq("order_id", params.orderId);
    if (error) {
      console.error("PaymentRepository.updateStatus error:", error);
      return false;
    }
    return true;
  }
  async getByOrderId(orderId) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return null;
    const { data, error } = await supabase.from("payments").select("*").eq("order_id", orderId).maybeSingle();
    if (error || !data) return null;
    return this.mapRow(data);
  }
  async getByPaymentId(paymentId) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return null;
    const { data, error } = await supabase.from("payments").select("*").eq("payment_id", paymentId).maybeSingle();
    if (error || !data) return null;
    return this.mapRow(data);
  }
  async getByProviderEventId(eventId) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return null;
    const { data, error } = await supabase.from("payments").select("*").eq("provider_event_id", eventId).maybeSingle();
    if (error || !data) return null;
    return this.mapRow(data);
  }
  async expireStaleOrders(olderThanHours = 24) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return 0;
    const cutoff = new Date(Date.now() - olderThanHours * 60 * 60 * 1e3).toISOString();
    const { data, error } = await supabase.from("payments").update({
      status: "expired",
      updated_at: (/* @__PURE__ */ new Date()).toISOString()
    }).eq("status", "created").lt("created_at", cutoff).select("id");
    if (error) {
      console.error("PaymentRepository.expireStaleOrders error:", error);
      return 0;
    }
    return data ? data.length : 0;
  }
  async listAll(limit = 50, status) {
    const supabase = getSupabaseAdmin();
    if (!supabase) return [];
    let query = supabase.from("payments").select("*, profiles:user_id(email, full_name)").order("created_at", { ascending: false }).limit(limit);
    if (status && status !== "all") {
      query = query.eq("status", status);
    }
    const { data, error } = await query;
    if (error || !data) {
      console.error("PaymentRepository.listAll error:", error);
      return [];
    }
    return data.map((row) => ({
      ...this.mapRow(row),
      userEmail: row.profiles?.email || void 0
    }));
  }
  async getMetrics() {
    const supabase = getSupabaseAdmin();
    if (!supabase) {
      return { capturedCount: 0, createdCount: 0, failedCount: 0, totalAmountSubunits: 0 };
    }
    const { data, error } = await supabase.from("payments").select("status, amount_subunits");
    if (error || !data) {
      return { capturedCount: 0, createdCount: 0, failedCount: 0, totalAmountSubunits: 0 };
    }
    let capturedCount = 0;
    let createdCount = 0;
    let failedCount = 0;
    let totalAmountSubunits = 0;
    for (const row of data) {
      if (row.status === "captured") {
        capturedCount++;
        totalAmountSubunits += row.amount_subunits || 0;
      } else if (row.status === "created") {
        createdCount++;
      } else if (row.status === "failed") {
        failedCount++;
      }
    }
    return { capturedCount, createdCount, failedCount, totalAmountSubunits };
  }
  mapRow(data) {
    return {
      id: data.id,
      workspaceId: data.workspace_id,
      userId: data.user_id,
      orderId: data.order_id,
      paymentId: data.payment_id,
      providerEventId: data.provider_event_id,
      signature: data.signature,
      planId: data.plan_id,
      amountSubunits: data.amount_subunits,
      currency: data.currency,
      status: data.status,
      isSimulated: Boolean(data.is_simulated),
      idempotencyKey: data.idempotency_key,
      createdAt: data.created_at,
      updatedAt: data.updated_at
    };
  }
};
