import { Router as Router5 } from "express";

// apps/api/src/repositories/salesRepository.ts
init_supabaseClient();
var SalesRepository = class {
  async createLead(lead) {
    const supabase = getSupabaseAdmin();
    if (!supabase) {
      return null;
    }
    const { data, error } = await supabase.from("sales_leads").insert({
      company_name: lead.companyName,
      contact_name: lead.contactName,
      email: lead.email,
      team_size: lead.teamSize,
      message: lead.message,
      status: "new"
    }).select().single();
    if (error || !data) {
      console.error("SalesRepository.createLead error:", error);
      return null;
    }
    return {
      id: data.id,
      companyName: data.company_name,
      contactName: data.contact_name,
      email: data.email,
      teamSize: data.team_size,
      message: data.message,
      status: data.status,
      createdAt: data.created_at,
      updatedAt: data.updated_at
    };
  }
};
var salesRepository = new SalesRepository();

