// packages/presentation-engine/layouts/layoutEngine.ts
function computeSlideLayout(input, theme, slideIndex = 0) {
  const slideId = input.id || `slide_${slideIndex + 1}`;
  const layout = resolveCompatibleLayout(input.purpose, input.preferredLayout);
  let elements;
  switch (layout) {
    case "cover":
      elements = computeCoverLayout(input, theme, slideId);
      break;
    case "split":
      elements = computeSplitLayout(input, theme, slideId);
      break;
    case "bento":
      elements = computeBentoLayout(input, theme, slideId);
      break;
    case "metrics-focus":
      elements = computeMetricsLayout(input, theme, slideId);
      break;
    case "timeline":
      elements = computeTimelineLayout(input, theme, slideId);
      break;
    case "comparison":
      elements = computeComparisonLayout(input, theme, slideId);
      break;
    case "quote":
    case "standard":
    default:
      elements = computeStandardLayout(input, theme, slideId);
      break;
  }
  return {
    layout,
    elements
  };
}

// packages/presentation-engine/typography/fontMapping.ts
var FONT_MAPPING_TABLE = {
  inter: {
    name: "Inter",
    webFont: "Inter, sans-serif",
    pptxSafeFont: "Arial",
    pdfStandardFont: "Helvetica",
    category: "sans-serif"
  },
  roboto: {
    name: "Roboto",
    webFont: "Roboto, sans-serif",
    pptxSafeFont: "Arial",
    pdfStandardFont: "Helvetica",
    category: "sans-serif"
  },
  outfit: {
    name: "Outfit",
    webFont: "Outfit, sans-serif",
    pptxSafeFont: "Calibri",
    pdfStandardFont: "Helvetica",
    category: "sans-serif"
  },
  playfair: {
    name: "Playfair Display",
    webFont: '"Playfair Display", Georgia, serif',
    pptxSafeFont: "Georgia",
    pdfStandardFont: "Times",
    category: "serif"
  },
  merriweather: {
    name: "Merriweather",
    webFont: "Merriweather, Georgia, serif",
    pptxSafeFont: "Georgia",
    pdfStandardFont: "Times",
    category: "serif"
  },
  fira: {
    name: "Fira Code",
    webFont: '"Fira Code", monospace',
    pptxSafeFont: "Consolas",
    pdfStandardFont: "Courier",
    category: "monospace"
  },
  sans: {
    name: "Standard Sans",
    webFont: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
    pptxSafeFont: "Calibri",
    pdfStandardFont: "Helvetica",
    category: "sans-serif"
  },
  serif: {
    name: "Standard Serif",
    webFont: 'Georgia, Cambria, "Times New Roman", Times, serif',
    pptxSafeFont: "Georgia",
    pdfStandardFont: "Times",
    category: "serif"
  }
};
function resolveTypographyToken(fontKeyOrName) {
  if (!fontKeyOrName) {
    return FONT_MAPPING_TABLE.inter;
  }
  const normalized = fontKeyOrName.toLowerCase().replace(/['"]/g, "").trim();
  for (const [key, def] of Object.entries(FONT_MAPPING_TABLE)) {
    if (normalized.includes(key) || normalized.includes(def.name.toLowerCase())) {
      return def;
    }
  }
  if (normalized.includes("serif")) {
    return FONT_MAPPING_TABLE.serif;
  }
  if (normalized.includes("mono")) {
    return FONT_MAPPING_TABLE.fira;
  }
  return FONT_MAPPING_TABLE.inter;
}

// packages/presentation-engine/geometry/coordinateConverter.ts
function clampBounds(bounds) {
  const x = Math.max(0, Math.min(100, bounds.x));
  const y = Math.max(0, Math.min(100, bounds.y));
  const width = Math.max(1, Math.min(100 - x, bounds.width));
  const height = Math.max(1, Math.min(100 - y, bounds.height));
  return {
    ...bounds,
    x,
    y,
    width,
    height
  };
}
function toPptxInches(bounds, slideWidthInches = 13.333, slideHeightInches = 7.5) {
  const clamped = clampBounds(bounds);
  return {
    x: clamped.x / 100 * slideWidthInches,
    y: clamped.y / 100 * slideHeightInches,
    w: clamped.width / 100 * slideWidthInches,
    h: clamped.height / 100 * slideHeightInches
  };
}
function toPdfPoints(bounds, pageWidthPoints = 1920, pageHeightPoints = 1080) {
  const clamped = clampBounds(bounds);
  return {
    x: clamped.x / 100 * pageWidthPoints,
    y: clamped.y / 100 * pageHeightPoints,
    width: clamped.width / 100 * pageWidthPoints,
    height: clamped.height / 100 * pageHeightPoints
  };
}

// packages/presentation-engine/theme/chartPaletteResolver.ts
function buildChartPaletteFromColors(colors) {
  const primary = colors.primary || "#2874F0";
  const secondary = colors.secondary || "#FB641B";
  const accent = colors.accent || "#FFE500";
  return [
    primary,
    secondary,
    accent,
    "#10B981",
    "#6366F1",
    "#EC4899",
    "#06B6D4"
  ];
}

// packages/presentation-engine/theme/brandThemeResolver.ts
function resolveBrandTheme(brand, customTheme) {
  const brandName = brand?.name || "Enterprise Suite";
  const primaryColor = brand?.colors?.[0] || "#2874F0";
  const secondaryColor = brand?.colors?.[1] || "#FB641B";
  const accentColor = brand?.colors?.[2] || "#FFE500";
  const headingFontDef = resolveTypographyToken(brand?.typography?.primary || "Inter");
  const bodyFontDef = resolveTypographyToken(brand?.typography?.secondary || brand?.typography?.primary || "Inter");
  const chartPalette = buildChartPaletteFromColors({
    primary: primaryColor,
    secondary: secondaryColor,
    accent: accentColor
  });
  const baseTheme = {
    id: `theme_${brand?.id || "brand_default"}`,
    name: `Signature ${brandName}`,
    colors: {
      primary: primaryColor,
      secondary: secondaryColor,
      accent: accentColor,
      background: "#0F172A",
      surface: "rgba(30, 41, 59, 0.75)",
      text: "#FFFFFF",
      mutedText: "#94A3B8",
      border: "rgba(255, 255, 255, 0.12)",
      chartPalette
    },
    typography: {
      headingFont: headingFontDef.webFont,
      bodyFont: bodyFontDef.webFont,
      pptxSafeHeadingFont: headingFontDef.pptxSafeFont,
      pptxSafeBodyFont: bodyFontDef.pptxSafeFont
    },
    overlay: 0.45,
    cornerRadius: 16,
    lineStyle: `linear-gradient(90deg, ${primaryColor}, ${secondaryColor})`
  };
  if (!customTheme) {
    return baseTheme;
  }
  return {
    ...baseTheme,
    ...customTheme,
    colors: {
      ...baseTheme.colors,
      ...customTheme.colors
    },
    typography: {
      ...baseTheme.typography,
      ...customTheme.typography
    }
  };
}

// packages/presentation-engine/validation/documentValidator.ts
function validatePresentationDocument(doc) {
  const errors = [];
  const warnings = [];
  if (!doc.id) errors.push("Document missing required id.");
  if (typeof doc.schemaVersion !== "number" || doc.schemaVersion < 1) {
    errors.push("Document schemaVersion must be an integer >= 1.");
  }
  if (typeof doc.version !== "number" || doc.version < 1) {
    errors.push("Document version must be an integer >= 1.");
  }
  if (!doc.slides || !Array.isArray(doc.slides) || doc.slides.length === 0) {
    errors.push("Document must contain at least 1 slide in slides array.");
  }
  doc.slides.forEach((slide, index) => {
    if (slide.index !== index) {
      warnings.push(`Slide index mismatch at position ${index}: slide.index is ${slide.index}.`);
    }
    if (!slide.title || slide.title.trim().length === 0) {
      errors.push(`Slide at index ${index} is missing a title.`);
    }
    slide.elements.forEach((el) => {
      if (!el.id) errors.push(`Element in slide ${index} is missing an id.`);
      const { x, y, width, height } = el.bounds;
      if (x < 0 || x > 100) errors.push(`Element ${el.id} bounds.x (${x}) outside 0-100% range.`);
      if (y < 0 || y > 100) errors.push(`Element ${el.id} bounds.y (${y}) outside 0-100% range.`);
      if (width <= 0 || width > 100) errors.push(`Element ${el.id} bounds.width (${width}) invalid.`);
      if (height <= 0 || height > 100) errors.push(`Element ${el.id} bounds.height (${height}) invalid.`);
    });
    const factualElements = slide.elements.filter(
      (el) => "provenance" in el
    );
    const provReport = validateSlideProvenance(factualElements);
    warnings.push(...provReport.warnings);
  });
  return {
    isValid: errors.length === 0,
    errors,
    warnings
  };
}

