var PresentationError = class extends Error {
  constructor(params) {
    super(params.message);
    this.name = "PresentationError";
    this.status = params.status;
    this.code = params.code;
    this.kind = params.kind;
    this.retryable = params.retryable ?? false;
    this.details = params.details;
  }
};
function classifyGeminiError(err) {
  const status = Number(err?.status || err?.code || err?.statusCode || 0);
  const rawMessage = typeof err === "string" ? err : err?.message || JSON.stringify(err) || "";
  const msgLower = rawMessage.toLowerCase();
  if (status === 400 || msgLower.includes("invalid_argument") || msgLower.includes("must be a value") || msgLower.includes("bad request") || msgLower.includes("schema validation") || msgLower.includes("response_format")) {
    return {
      kind: "VALIDATION",
      statusCode: 400,
      code: "PRESENTATION_INVALID_REQUEST",
      message: rawMessage || "Invalid request parameter or schema specification.",
      retryable: false,
      shouldFallback: false,
      originalError: err
    };
  }
  if (status === 401 || status === 403 || msgLower.includes("unauthenticated") || msgLower.includes("permission_denied") || msgLower.includes("api_key_invalid") || msgLower.includes("unauthorized")) {
    return {
      kind: "AUTH",
      statusCode: status === 403 ? 403 : 401,
      code: "PRESENTATION_AUTH_ERROR",
      message: "Authentication failed for the AI provider. Please verify API configuration.",
      retryable: false,
      shouldFallback: false,
      originalError: err
    };
  }
  if (status === 404 || msgLower.includes("not_found") || msgLower.includes("is not found") || msgLower.includes("does not exist")) {
    return {
      kind: "MODEL_UNAVAILABLE",
      statusCode: 404,
      code: "PRESENTATION_MODEL_UNAVAILABLE",
      message: "The requested presentation model is unavailable in this project.",
      retryable: false,
      shouldFallback: true,
      originalError: err
    };
  }
  if (status === 429 || msgLower.includes("resource_exhausted") || msgLower.includes("quota exceeded") || msgLower.includes("rate limit")) {
    const isFreeTierExhausted = msgLower.includes("free_tier") || msgLower.includes("freetier");
    let retryDelayMs;
    const retryMatch = rawMessage.match(/retry in ([\d\.]+)s/i);
    if (retryMatch && retryMatch[1]) {
      const seconds = parseFloat(retryMatch[1]);
      if (seconds <= 60) {
        retryDelayMs = Math.ceil(seconds * 1e3);
      }
    }
    const quotaMessage = isFreeTierExhausted ? "Google AI Studio Free Tier rate limit reached. Rotate to configured alternate model or attach a Pay-As-You-Go API key." : "Presentation model quota is currently exhausted. Falling over to configured alternate model.";
    return {
      kind: "QUOTA",
      statusCode: 429,
      code: isFreeTierExhausted ? "PRESENTATION_FREE_TIER_QUOTA_EXHAUSTED" : "PRESENTATION_QUOTA_EXHAUSTED",
      message: quotaMessage,
      retryable: Boolean(retryDelayMs && retryDelayMs <= 5e3),
      retryDelayMs,
      isFreeTierExhausted,
      shouldFallback: true,
      originalError: err
    };
  }
  if (status === 500 || status === 502 || status === 503 || status === 504 || msgLower.includes("high demand") || msgLower.includes("unavailable") || msgLower.includes("internal error") || msgLower.includes("timeout") || msgLower.includes("aborted") || msgLower.includes("aborterror") || msgLower.includes("econnreset") || msgLower.includes("etimedout")) {
    return {
      kind: "TRANSIENT",
      statusCode: status >= 500 ? status : 503,
      code: "PRESENTATION_TRANSIENT_FAILURE",
      message: "AI provider is temporarily experiencing high demand or transient timeout.",
      retryable: true,
      retryDelayMs: 1e3,
      shouldFallback: true,
      originalError: err
    };
  }
  return {
    kind: "UNKNOWN",
    statusCode: 500,
    code: "PRESENTATION_GENERATION_FAILED",
    message: rawMessage || "An unexpected error occurred during presentation generation.",
    retryable: false,
    shouldFallback: false,
    originalError: err
  };
}

// apps/api/src/modules/presentation/presentationGeminiClient.ts
var PresentationGeminiClient = class {
  constructor() {
    // Hard execution invariants to prevent runaway cascade loops
    this.MAX_MODELS = 3;
    this.MAX_RETRIES_PER_MODEL = 1;
    this.MAX_TOTAL_ATTEMPTS = 6;
    this.DEFAULT_TIMEOUT_MS = 18e4;
    // 180 seconds global budget across fallbacks
    this.PER_ATTEMPT_TIMEOUT_MS = 9e4;
  }
  // 90 seconds per individual LLM call
  /**
   * Executes a structured JSON LLM call with bounded retries and model fallbacks.
   */
  async executeStructured(params) {
    const {
      generationId,
      stage,
      policyName = "production",
      userInput,
      systemInstruction,
      responseSchema,
      semanticValidator,
      timeoutMs = this.DEFAULT_TIMEOUT_MS
    } = params;
    const resolved = resolvePresentationConfig(stage, policyName);
    const billingContext = getGeminiBillingContext();
    const isPayAsYouGo = resolved.isPayAsYouGo || billingContext.tier === "pay_as_you_go" || billingContext.tier === "enterprise";
    const effectiveMaxRetries = isPayAsYouGo ? 2 : this.MAX_RETRIES_PER_MODEL;
    const ai = getServerAI();
    const modelChain = [resolved.model, ...resolved.fallbacks].slice(0, this.MAX_MODELS);
    const telemetryHistory = [];
    let totalAttempts = 0;
    const globalDeadline = Date.now() + timeoutMs;
    let lastError = null;
    for (let modelIdx = 0; modelIdx < modelChain.length; modelIdx++) {
      const currentModel = modelChain[modelIdx];
      let modelRetries = 0;
      while (modelRetries <= effectiveMaxRetries) {
        if (Date.now() >= globalDeadline) {
          throw new PresentationError({
            message: `Presentation generation timed out after ${timeoutMs}ms.`,
            status: 504,
            code: "PRESENTATION_TIMEOUT",
            kind: "TRANSIENT",
            retryable: false
          });
        }
        if (totalAttempts >= this.MAX_TOTAL_ATTEMPTS) {
          throw new PresentationError({
            message: `Maximum generation attempt budget (${this.MAX_TOTAL_ATTEMPTS}) exceeded.`,
            status: 503,
            code: "PRESENTATION_ATTEMPT_BUDGET_EXCEEDED",
            kind: "TRANSIENT",
            retryable: false
          });
        }
        totalAttempts++;
        const attemptStartTime = Date.now();
        const isFallback = modelIdx > 0;
        console.log(
          `[PresentationGeminiClient] [gen:${generationId.slice(0, 8)}] Stage:${stage} Attempt:${totalAttempts} (Model: ${currentModel}${isFallback ? " [FALLBACK]" : ""}, Tier: ${billingContext.tier})`
        );
        const remainingGlobalTime = globalDeadline - Date.now();
        const attemptTimeout = Math.min(this.PER_ATTEMPT_TIMEOUT_MS, remainingGlobalTime);
        const abortController = new AbortController();
        const timeoutHandle = setTimeout(() => abortController.abort(), attemptTimeout);
        try {
          const config = {
            systemInstruction,
            responseMimeType: "application/json",
            abortSignal: abortController.signal
          };
          if (responseSchema) {
            config.responseSchema = responseSchema;
          }
          const response = await ai.models.generateContent({
            model: currentModel,
            contents: userInput,
            config
          });
          clearTimeout(timeoutHandle);
          const latencyMs = Date.now() - attemptStartTime;
          const rawText = response.text;
          if (!rawText || !rawText.trim()) {
            throw new PresentationError({
              message: "Gemini model returned an empty text payload.",
              status: 502,
              code: "PRESENTATION_EMPTY_RESPONSE",
              kind: "TRANSIENT",
              retryable: true
            });
          }
          const cleanJson = rawText.replace(/```json\n?|\n?```/g, "").trim();
          let parsed;
          try {
            parsed = JSON.parse(cleanJson);
          } catch (jsonErr) {
            throw new PresentationError({
              message: `Malformed JSON returned by model: ${jsonErr?.message}`,
              status: 502,
              code: "PRESENTATION_MALFORMED_JSON",
              kind: "TRANSIENT",
              retryable: true,
              details: { preview: cleanJson.slice(0, 100) }
            });
          }
          if (semanticValidator) {
            const validation = semanticValidator(parsed);
            if (!validation.isValid) {
              const errDetails = validation.errors ? validation.errors.join("; ") : "Unknown schema mismatch";
              throw new PresentationError({
                message: `Application-level semantic validation failed: ${errDetails}`,
                status: 502,
                code: "PRESENTATION_SEMANTIC_VALIDATION_FAILED",
                kind: "TRANSIENT",
                retryable: true,
                details: { errors: validation.errors }
              });
            }
          }
          telemetryHistory.push({
            generationId,
            stage,
            requestedModel: modelChain[0],
            actualModel: currentModel,
            attempt: modelRetries + 1,
            totalAttempts,
            latencyMs,
            fallbackUsed: isFallback,
            success: true,
            billingTier: billingContext.tier,
            keySource: billingContext.keySource
          });
          return {
            data: parsed,
            modelUsed: currentModel,
            latencyMs,
            telemetry: telemetryHistory
          };
        } catch (err) {
          clearTimeout(timeoutHandle);
          const latencyMs = Date.now() - attemptStartTime;
          const classified = classifyGeminiError(err);
          lastError = classified;
          telemetryHistory.push({
            generationId,
            stage,
            requestedModel: modelChain[0],
            actualModel: currentModel,
            attempt: modelRetries + 1,
            totalAttempts,
            latencyMs,
            errorKind: classified.kind,
            fallbackUsed: isFallback,
            success: false,
            billingTier: billingContext.tier,
            keySource: billingContext.keySource
          });
          console.warn(
            `[PresentationGeminiClient] [gen:${generationId.slice(0, 8)}] Attempt on ${currentModel} failed: [${classified.kind}] ${classified.message}`
          );
          if (!classified.shouldFallback) {
            throw new PresentationError({
              message: classified.message,
              status: classified.statusCode,
              code: classified.code,
              kind: classified.kind,
              retryable: false,
              details: err?.details || err
            });
          }
          if (classified.kind === "QUOTA" && billingContext.poolSize > 1) {
            rotateGeminiClient();
            console.log(
              `[PresentationGeminiClient] Key pool active: rotated to next API key and retrying ${currentModel}...`
            );
            modelRetries++;
            continue;
          }
          if (classified.retryable && modelRetries < effectiveMaxRetries) {
            const delay = isPayAsYouGo ? Math.min(600 * Math.pow(1.5, modelRetries) + Math.random() * 200, 2e3) : classified.retryDelayMs || 1500;
            console.log(
              `[PresentationGeminiClient] Retrying transient failure on ${currentModel} in ${Math.round(delay)}ms...`
            );
            await new Promise((res) => setTimeout(res, delay));
            modelRetries++;
            continue;
          }
          if (classified.kind === "QUOTA" && modelIdx < modelChain.length - 1) {
            const delay = isPayAsYouGo ? 300 : classified.retryDelayMs || 2500;
            console.log(
              `[PresentationGeminiClient] Quota backoff (${billingContext.tier}): waiting ${delay}ms before rotating to next model...`
            );
            await new Promise((res) => setTimeout(res, delay));
          }
          break;
        }
      }
    }
    throw new PresentationError({
      message: `Presentation ${stage} generation failed across all configured models: ${lastError?.message || "Unknown error"}`,
      status: lastError?.statusCode || 503,
      code: lastError?.code || "PRESENTATION_ALL_MODELS_EXHAUSTED",
      kind: lastError?.kind || "PROVIDER",
      retryable: false,
      details: { telemetry: telemetryHistory }
    });
  }
};
var presentationGeminiClient = new PresentationGeminiClient();

