        pdf.setFontSize(36);
        pdf.text(el.value, pt.x + 24, pt.y + 54);
        applyPdfTextColor(pdf, theme.colors.text || "#FFFFFF");
        pdf.setFont("helvetica", "normal");
        pdf.setFontSize(16);
        const splitLabel = pdf.splitTextToSize(el.label, pt.width - 48);
