var VideoAssetResolver = class {
  async resolve(assetId, workspaceId) {
    if (!assetId) return null;
    if (assetId.startsWith("data:")) {
      const match = assetId.match(/^data:([^;]+);base64,(.+)$/);
      const mimeType = match ? match[1] : "image/png";
      const buffer = match ? Buffer.from(match[2], "base64") : Buffer.alloc(0);
      return {
        assetId: "data_uri",
        url: assetId,
        mimeType,
        name: "uploaded_frame",
        buffer
      };
    }
    if (assetId.startsWith("http://") || assetId.startsWith("https://")) {
      return {
        assetId: "remote_url",
        url: assetId,
        mimeType: "image/png",
        name: "remote_asset"
      };
    }
    const asset = await assetRepository.getById(assetId, workspaceId);
    if (!asset) {
      console.warn(`[VideoAssetResolver] Asset ${assetId} not found in workspace ${workspaceId}`);
      return null;
    }
    const signedUrl = await storageService.getSignedUrl(asset.storagePath, 3600);
    if (!signedUrl) {
      console.warn(`[VideoAssetResolver] Failed to generate signed URL for asset ${assetId}`);
      return null;
    }
    return {
      assetId: asset.id,
      url: signedUrl,
      mimeType: asset.mimeType || "image/png",
      name: asset.name
    };
  }
  async resolveAsBuffer(assetId, workspaceId) {
    const resolved = await this.resolve(assetId, workspaceId);
    if (!resolved) return null;
    if (resolved.buffer) return resolved;
    try {
      const supabase = getSupabaseAdmin();
      if (supabase) {
        const asset = await assetRepository.getById(assetId, workspaceId);
        if (asset) {
          const { data, error } = await supabase.storage.from(asset.storageBucket || "user-assets").download(asset.storagePath);
          if (data && !error) {
            const arrayBuffer = await data.arrayBuffer();
            resolved.buffer = Buffer.from(arrayBuffer);
            return resolved;
          }
        }
      }
      const res = await fetch(resolved.url);
      if (res.ok) {
        const arrayBuffer = await res.arrayBuffer();
        resolved.buffer = Buffer.from(arrayBuffer);
      }
    } catch (err) {
      console.error(`[VideoAssetResolver] Error downloading asset buffer ${assetId}:`, err);
    }
    return resolved;
  }
};
var videoAssetResolver = new VideoAssetResolver();

// apps/api/src/modules/videoGeneration/payloads/omniPayloadBuilder.ts
var OmniPayloadBuilder = class {
  /**
   * Compiles the visual prompt with integrated negative constraints and edit invariants.
   */
  compilePrompt(request) {
    const parts = [];
    if (request.mode === "edit_video" && request.editInstruction) {
      let editCmd = request.editInstruction.trim();
      if (!editCmd.toLowerCase().includes("keep everything else")) {
        editCmd += ". Keep everything else the same.";
      }
      parts.push(editCmd);
    } else {
      parts.push(request.prompt.trim());
      if (request.audioIntent && request.audioIntent !== "none") {
        const audioMap = {
          ambient: "Include atmospheric natural environmental ambient sound matching the scene.",
          music: "Include cinematic background musical score matching the rhythm and tone.",
          sfx: "Include synchronized Foley and realistic sound effects for actions.",
          dialogue: "Include clear, natural spoken character dialogue.",
          dialogue_sfx: "Include synchronized character dialogue and rich Foley sound effects.",
          cinematic_soundscape: "Include a full cinematic soundscape with synchronized dialogue, orchestral music, and dynamic Foley."
        };
        const directive = audioMap[request.audioIntent];
        if (directive) {
          parts.push(`Audio Direction: ${directive}`);
        }
      }
      if (request.scenes && request.scenes.length > 0) {
        const sceneScript = request.scenes.map(
          (s, idx) => `[Scene ${idx + 1} (${s.timeRange || s.durationSeconds + "s"})]: ${s.description}. Camera: ${s.camera}. Action: ${s.subjectAction}.`
        ).join(" ");
        parts.push(`Shot Sequence: ${sceneScript}`);
      }
    }
    const defaultNegativeConstraints = [
      "No sudden camera glitches",
      "no morphing anatomy",
      "no frame stutter",
      "no text artifacts",
      "no watermark"
    ];
    parts.push(`Quality Constraints: ${defaultNegativeConstraints.join(", ")}.`);
    return parts.join("\n\n");
  }
  /**
   * Builds the full Omni Interaction API submission payload.
   */
  async build(request, workspaceId) {
    const compiledText = this.compilePrompt(request);
    const inputParts = [
      { text: compiledText }
    ];
    if (request.references && request.references.length > 0) {
      for (const ref of request.references.slice(0, 3)) {
        const resolved = await videoAssetResolver.resolveAsBuffer(ref.assetId, workspaceId);
        if (resolved?.buffer) {
          inputParts.push({
            media: {
              mime_type: resolved.mimeType,
              data: resolved.buffer.toString("base64")
            }
          });
        }
      }
    } else if (request.startFrameAssetId) {
      const resolved = await videoAssetResolver.resolveAsBuffer(request.startFrameAssetId, workspaceId);
      if (resolved?.buffer) {
        inputParts.push({
          media: {
            mime_type: resolved.mimeType,
            data: resolved.buffer.toString("base64")
          }
        });
      }
    }
    const payload = {
      model: "gemini-omni-1.1-flash",
      input: inputParts,
      store: true,
      // Always store=true so subsequent previous_interaction_id follow-up edits work
      response_format: {
        type: "video",
        delivery: "uri"
      }
    };
    if (request.previousInteractionId) {
      payload.previous_interaction_id = request.previousInteractionId;
    }
    return payload;
  }
};
